using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class RepairReverseTurnJoin {public static string Main(){EditorApplication.delayCall+=()=>{try{EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");float S(float a,float b,float t)=>Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,t));var tree=Object.FindObjectsByType<Collider>().Where(c=>c.name.IndexOf("trunk",StringComparison.OrdinalIgnoreCase)>=0).Select(c=>c.bounds.center).ToArray();var mf=GameObject.Find("Ground_480_320").GetComponent<MeshFilter>();var mesh=mf.sharedMesh;if(!AssetDatabase.GetAssetPath(mesh).StartsWith("Assets/Track/BackyardReverseCorrections/"))throw new Exception("Owned mesh required");var v=mesh.vertices;int count=0;for(int i=0;i<v.Length;i++){var p=mf.transform.TransformPoint(v[i]);float distance=Vector2.Distance(new(p.x,p.z),new(234,-31));float w=1-S(8,14,distance);if(w<=0)continue;foreach(var t in tree){float d=Vector2.Distance(new(t.x,t.z),new(p.x,p.z));if(d<2.5f)w*=S(.9f,2.5f,d);}float target=60.1f+.14f*(p.x-232)+.095f*(p.z+32);p.y=Mathf.Lerp(p.y,target,w);v[i]=mf.transform.InverseTransformPoint(p);count++;}mesh.vertices=v;mesh.RecalculateNormals();mesh.RecalculateBounds();mf.GetComponent<MeshCollider>().sharedMesh=null;mf.GetComponent<MeshCollider>().sharedMesh=mesh;EditorUtility.SetDirty(mesh);Physics.SyncTransforms();var race=Object.FindAnyObjectByType<RaceDirector>();var road=race.road;road.Initialize();var course=race.GetComponent<BackyardForwardCourse>();var lands=course.landingStations.Select(s=>road.At(s,out _)).ToArray();for(int i=0;i<road.points.Length;i++){var p=road.points[i];if(Vector2.Distance(new(p.x,p.z),new(234,-31))<14){p.y=Racer.Editor.BackyardReverseAuthoring.Ground(p);road.points[i]=p;}}typeof(RaceRoad).GetField("distance",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(road,null);road.Initialize();for(int j=0;j<3;j++){course.launchStations[j]=road.Project(course.flightStarts[j],out _);course.landingStations[j]=road.Project(lands[j],out _);}var layout=Object.FindAnyObjectByType<ForestLayout>();layout.jumpStarts=course.launchStations;layout.jumpEnds=course.landingStations;EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();Racer.Editor.BackyardReverseAuthoring.ExportReverse();File.WriteAllText("Docs/BackyardReverseCorrections/turn-join.txt","Removed nearest-segment height discontinuity across bend with one continuous local sloping support field; preserved existing tree-foot supports; vertices="+count);}catch(Exception e){File.WriteAllText("Docs/BackyardReverseCorrections/turn-join-error.txt",e.ToString());}};return "Repair actual sharp surface join inside the dump approach bend";}}
